import {ExpandButton} from '@github-ui/expand-button'

interface ExpandPanelButtonProps {
  expanded?: boolean
  onToggleExpanded: () => void
  ariaControls: string
  ref?: React.Ref<HTMLButtonElement>
}

export const ExpandPanelButton = ({ref, expanded, onToggleExpanded, ariaControls}: ExpandPanelButtonProps) => (
  <ExpandButton
    expanded={expanded}
    alignment="right"
    ariaLabel={expanded ? 'Collapse help panel' : 'Expand help panel'}
    ariaControls={ariaControls}
    tooltipDirection="nw"
    testid="help-panel-button"
    ref={ref}
    onToggleExpanded={onToggleExpanded}
  />
)

ExpandPanelButton.displayName = 'ExpandPanelButton'
