import type {EditorView} from '@codemirror/view'
import {linter} from '@github-ui/code-mirror/linter'
import {html} from 'lit-html'

import {yamlHelpPanel} from '../codemirror-next-autocomplete-util'
import {getRootRule} from './rules'
import lint from '../linters'
import {buildLintMarks} from '../../linter-util-next'
import type {LintMessage} from '../../linter-util'

/**
 * Extracts the YAML frontmatter region from a markdown document.
 * Frontmatter is delimited by `---` at the start of the file.
 *
 * Returns the YAML content (without delimiters) and the line offset
 * of the first YAML line within the original document so lint
 * positions can be mapped back correctly.
 */
export function extractFrontmatter(text: string): {yaml: string; lineOffset: number} | null {
  const lines = text.split('\n')

  // First line must be the opening `---`
  const firstLine = lines[0]
  if (lines.length === 0 || !firstLine || !/^---\s*$/.test(firstLine)) {
    return null
  }

  // Find the closing `---`
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i]
    if (line !== undefined && /^---\s*$/.test(line)) {
      const yamlLines = lines.slice(1, i)
      return {
        yaml: yamlLines.join('\n'),
        lineOffset: 1, // YAML content starts on line 1 (after the opening ---)
      }
    }
  }

  // No closing delimiter found
  return null
}

/**
 * Offsets all lint message positions by the given number of lines.
 * This maps positions from the extracted YAML back to the full document.
 */
function offsetMessages(messages: LintMessage[], lineOffset: number): LintMessage[] {
  return messages.map(msg => ({
    ...msg,
    from: {...msg.from, line: msg.from.line + lineOffset},
    to: {...msg.to, line: msg.to.line + lineOffset},
  }))
}

// Autocomplete is intentionally not included here. The triage agent config is a
// .md file, so the base editor loads the Markdown language which configures its
// own autocompletion (emoji etc.). Adding yamlAutocomplete would create a second
// autocompletion() extension with a conflicting `override` config, causing a
// "Config merge conflict for field override" error at runtime.
export function triageAgentEditor() {
  return [yamlHelpPanel(), linter(triageAgentLintSource)]
}

async function triageAgentLintSource(view: EditorView) {
  const text = view.state.doc.toString()
  const frontmatter = extractFrontmatter(text)

  if (!frontmatter) {
    // No frontmatter found — return a single error on line 0
    const firstLine = text.split('\n')[0] || ''
    return buildLintMarks(view, [
      {
        message: html`Config must start with YAML frontmatter (<code>---</code>)`,
        severity: 'error',
        from: {line: 0, ch: 0},
        to: {line: 0, ch: firstLine.length || 1},
      },
    ])
  }

  if (frontmatter.yaml.trim().length === 0) {
    // Empty frontmatter — return a single error
    return buildLintMarks(view, [
      {
        message: html`Frontmatter is empty — add configuration keys like <code>on</code> and
          <code>allowed-actions</code>`,
        severity: 'error',
        from: {line: 0, ch: 0},
        to: {line: 0, ch: 3},
      },
    ])
  }

  const annotations = await lint(frontmatter.yaml, getRootRule)
  const offsetAnnotations = offsetMessages(annotations, frontmatter.lineOffset)

  return buildLintMarks(view, offsetAnnotations)
}
