import type {CompletionContext, CompletionResult} from '@codemirror/autocomplete'
import {hoverTooltip, type EditorView, ViewPlugin} from '@codemirror/view'
import {Compartment} from '@codemirror/state'
import {linter} from '@github-ui/code-mirror/linter'
import {featureFlag} from '@github-ui/feature-flags'
import {yamlAutocompleteLanguageService, yamlHelpPanel} from '../codemirror-next-autocomplete-util'
import {setDocumentUri} from './document-uri'

// Lazy-loaded language service module
// Using a promise to prevent duplicate imports if called concurrently
let languageServicePromise: Promise<typeof import('./language-service')> | null = null

function getLanguageServiceModule() {
  if (!languageServicePromise) {
    languageServicePromise = (async () => {
      try {
        return await import('./language-service')
      } catch (err) {
        languageServicePromise = null
        throw err
      }
    })()
  }
  return languageServicePromise
}

/**
 * Compartment for dynamically loading inlay hints extensions.
 * This keeps @actions/languageservice scoped to workflow editor initialization,
 * not loaded by code that merely imports this module.
 */
const inlayHintsCompartment = new Compartment()

// Track views that have had inlay hints loaded
const inlayHintsLoadedViews = new WeakSet<EditorView>()

/**
 * ViewPlugin that lazy-loads the inlay hints module and reconfigures the editor.
 */
const lazyInlayHintsLoader = ViewPlugin.define(view => {
  if (!inlayHintsLoadedViews.has(view)) {
    inlayHintsLoadedViews.add(view)
    void (async () => {
      try {
        const module = await import('./inlay-hints')
        view.dispatch({
          effects: inlayHintsCompartment.reconfigure(module.workflowInlayHints()),
        })
      } catch (err) {
        // eslint-disable-next-line no-console
        console.error('[Language Service] Failed to load inlay hints:', err)
      }
    })()
  }
  return {}
})

// Capture feature flag state once at module load to ensure consistent behavior
const allowCaseFunction = featureFlag.isFeatureEnabled('actions_workflow_language_service_allow_case_function')
const allowCronTimezone = featureFlag.isFeatureEnabled('actions_scheduled_workflow_timezone_enabled')

export function workflowEditor(documentUri: string = '.github/workflows/workflow.yml') {
  // Store the document URI for use by language service functions
  setDocumentUri(documentUri)

  const autocompleteExtension = yamlAutocompleteLanguageService(workflowAutocompleteContext)

  const extensions = [autocompleteExtension, yamlHelpPanel(), linter(workflowYamlLintSource)]

  extensions.push(hoverTooltip(workflowHoverSource))
  // Use compartment for lazy-loading inlay hints (keeps @actions/languageservice
  // from being loaded until the editor is actually created)
  extensions.push(inlayHintsCompartment.of([]))
  extensions.push(lazyInlayHintsLoader)

  return extensions
}

async function workflowAutocompleteContext(context: CompletionContext): Promise<CompletionResult | null> {
  try {
    const module = await getLanguageServiceModule()
    return module.workflowAutocompleteContextWithLanguageService(context, allowCaseFunction, allowCronTimezone)
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error('[Language Service] Failed to load module:', err)
    return null
  }
}

async function workflowYamlLintSource(view: EditorView) {
  try {
    const module = await getLanguageServiceModule()
    return module.workflowYamlLintSourceWithLanguageService(view, allowCronTimezone)
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error('[Language Service] Failed to load module:', err)
    return []
  }
}

async function workflowHoverSource(view: EditorView, pos: number, _side: -1 | 1) {
  try {
    const module = await getLanguageServiceModule()
    const result = await module.workflowHoverWithLanguageService(view, pos)

    if (!result) {
      return null
    }

    return {
      pos: result.pos,
      end: result.end,
      above: true,
      create: () => ({dom: result.dom}),
    }
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error('[Language Service] Failed to load module:', err)
    return null
  }
}
