/* eslint @github-ui/github-monorepo/filename-convention: "off" */

import type {Transition} from '@github-ui/react-core/create-browser-history'
import {useIsDataRouterEnabled} from '@github-ui/react-core/future/use-is-data-router-enabled'
// eslint-disable-next-line import/no-deprecated
import {useBlocker as reactRouterUseBlocker, useBlockerLegacy} from '@github-ui/react-router'
import {SOFT_NAV_STATE} from '@github-ui/soft-nav/states'
import {useCallback, useEffect, useEffectEvent} from 'react'

/**
 * @source https://github.com/remix-run/react-router/issues/8139#issuecomment-1021457943
 */
export function usePrompt(message: string, when = true) {
  const isDataRouter = useIsDataRouterEnabled()

  // eslint-disable-next-line react-hooks/rules-of-hooks
  return isDataRouter ? usePromptDataRouter(message, when) : usePromptJSONRoute(message, when)
}

/**
 * @source https://github.com/remix-run/react-router/blob/00cb4d7b310663b2e84152700c05d3b503005e83/packages/react-router/lib/dom/lib.tsx#L3282
 */
function usePromptDataRouter(message: string, when = true) {
  const blocker = reactRouterUseBlocker(when)

  const resetBlocker = useEffectEvent(() => {
    blocker.reset?.()
    document.dispatchEvent(new Event(SOFT_NAV_STATE.END))
    document.dispatchEvent(new Event(SOFT_NAV_STATE.PROGRESS_BAR.END))
  })

  useEffect(() => {
    if (blocker.state === 'blocked') {
      const proceed = window.confirm(message)
      if (proceed) {
        // This timeout is needed to avoid a weird "race" on POP navigations
        // between the `window.history` revert navigation and the result of
        // `window.confirm`
        const timeoutId = setTimeout(() => {
          blocker.proceed?.()
        }, 0)
        return () => clearTimeout(timeoutId)
      } else {
        resetBlocker()
      }
    }
  }, [blocker, message])

  useEffect(() => {
    if (blocker.state === 'blocked' && !when) {
      resetBlocker()
    }
  }, [blocker, when])
}

function usePromptJSONRoute(message: string, when = true) {
  const blocker = useCallback(
    (tx: Transition) => {
      const response = window.confirm(message)
      if (response) {
        tx.retry()
      } else {
        document.dispatchEvent(new Event(SOFT_NAV_STATE.END))
        document.dispatchEvent(new Event(SOFT_NAV_STATE.PROGRESS_BAR.END))
      }
    },
    [message],
  )
  // eslint-disable-next-line import/no-deprecated
  return useBlockerLegacy(blocker, message, when)
}
